    "faq": "الأسئلة الشائعة",
    "faqA1": "لا. يمكن لأي شخص لديه رابط غرفتك الانضمام فورًا كضيف - بدون تسجيل أو بريد إلكتروني أو تنزيل مطلوب. فقط إنشاء غرفة يحتاج إلى حساب.",
    "faqA2": "لا. بالنسبة إلى YouTube وTwitch وVimeo، يحتاج الجميع إلى الرابط فقط. بالنسبة للملفات المحلية، يحتاج المضيف فقط إلى الملف، فهو يتدفق إلى أي شخص آخر. بالنسبة إلى Netflix، يحتاج المضيف فقط إلى اشتراك.",
    "faqA3": "نكتشف تلقائيًا مكان تشغيل الفيديو حاليًا وننقلك مباشرة إلى تلك اللحظة بالضبط. أنت دائمًا متزامن مع بقية الغرفة على الفور.",
    "faqA4": "يمكن لما يصل إلى 50 شخصًا المشاهدة معًا في غرفة واحدة في نفس الوقت.",
    "faqA5": "نعم، مجاني تماما للاستخدام. يمكنك إنشاء غرف ودعوة الأصدقاء والمشاهدة معًا دون أي تكلفة أو الحاجة إلى بطاقة ائتمان.",
    "faqA6": "يعمل SahaPlay على متصفحات Chrome وFirefox وSafari وEdge. لا حاجة للمكونات الإضافية أو الإضافات. بالنسبة لمشاركة الشاشة مع الصوت، نوصي باستخدام Chrome للحصول على أفضل النتائج.",
    "faqA7": "نعم - باستخدام ميزة مشاركة الشاشة. يشارك المضيف علامة تبويب Netflix أو Prime الخاصة به ويشاهدها جميع من في الغرفة في الوقت الفعلي. أنت بحاجة إلى الاشتراك في تلك الخدمات.",
    "faqA8": "نعم. يتم تشفير الرسائل الخاصة من طرف إلى طرف على جهازك قبل إرسالها. وهذا يعني أنه يمكنك أنت والمستلم فقط قراءتها، وليس نحن، وليس أي شخص آخر.",
