    "enterYourNameStepDesc": "ప్రదర్శన పేరును ఎంచుకోండి లేదా పూర్తి లక్షణాల కోసం మీ ఖాతాకు సైన్ ఇన్ చేయండి. మీరు దీన్ని దాటవేస్తే అతిథులు ఆటోమేటిక్‌గా యాదృచ్ఛిక పేరు పొందుతారు.",
