    "exploreFeaturesDesc": "పర్ఫెక్ట్ వాచ్ పార్టీ కోసం మీకు కావాల్సినవన్నీ — అన్నీ ఒకే చోట.",
    "exploreFeaturesTitle": "వేదిక ఫీచర్లు",
