    "privacyCardBody3": "వ్యక్తిగత సందేశాలను తొలగించండి, మొత్తం చాట్ చరిత్రను క్లియర్ చేయండి లేదా మీ ఖాతాను పూర్తిగా తీసివేయండి. మీ డేటా, మీ నియంత్రణ.",
    "privacyCardTitle1": "ఎండ్-టు-ఎండ్ ఎన్‌క్రిప్ట్ చేయబడింది",
