    "groupChat": "குழு அரட்டை",
    "groupChatDesc": "அறையில் உள்ள அனைவருடனும் அரட்டையடிக்கவும், தனிப்பயன் ஈமோஜிகளை அனுப்பவும், செய்திகளுக்குப் பதிலளிக்கவும்.",
    "groupChatF1": "அறையில் உள்ள அனைவருக்கும் செய்திகளை அனுப்பவும்",
    "groupChatF2": "ஈமோஜிகள் மூலம் செய்திகளுக்கு எதிர்வினையாற்றவும்",
