    "groupChatTitle": "குழு அரட்டை",
    "groupLobbyChat": "குழு லாபி அரட்டை",
    "hdStreaming": "மிருதுவான HD தரம்",
    "hdStreamingDesc": "உங்கள் திரையில் நேரடியாக உயர் வரையறை மற்றும் 4K மீடியா ஸ்ட்ரீம்களை அனுபவிக்கவும்.",
    "hdVideoSupport": "உயர் வரையறை வீடியோ ஆதரவு",
    "heroDescHowItWorks": "ஒரு அறையை உருவாக்கவும், நண்பர்களை அழைக்கவும், எந்த வீடியோவையும் சரியான ஒத்திசைவில் ஒன்றாகப் பார்க்கவும் - நிறுவல்கள் இல்லை, செருகுநிரல்கள் இல்லை, தொந்தரவு இல்லை.",
    "heroReadingTime": "5 நிமிடம் படித்தது · பின்தொடர எந்தக் கணக்கும் தேவையில்லை",
    "heroTitlePart1": "உங்களுக்கு தேவையான அனைத்தும்",
    "heroTitlePart2": "ஒன்றாக பார்க்கவும்",
    "hideVideos": "வீடியோக்களை மறை",
    "hideVideosDesc": "ஒன்றாக ஸ்ட்ரீமிங் செய்யும் போது அனைத்து பயனர் வீடியோக்களையும் மறை மற்றும் மறைக்கவும்",
    "hiwFinalCtaDesc": "இப்போது அதை நீங்களே அனுபவியுங்கள் —\\nஉங்கள் முதல் அறை 30 வினாடிகளில் தயாராகிவிடும்.",
    "hiwStep3WatchTogether": "ஒன்றாக பார்க்கவும்",
    "hostBanControlCheck": "தடைசெய்யப்பட்ட பயனர்களை நிரந்தரமாக அறைக்கு வெளியே வைத்திருங்கள்",
    "hostControls": "ஹோஸ்ட் கட்டுப்பாடுகள்",
    "hostControlsDesc": "தொகுப்பாளராக, யார் வீடியோக்களை இயக்கலாம், அரட்டையடிக்கலாம் அல்லது கேமராவை இயக்கலாம் என்பதைக் கட்டுப்படுத்தவும்",
    "hostControlsDescText": "உங்கள் வாட்ச் பார்ட்டியை வேடிக்கையாகவும் நட்பாகவும் வைத்திருங்கள். புரவலராக, யார் இணைப்புகளை அனுப்பலாம், கேமராக்களை இயக்கலாம், வீடியோக்களைத் தேடலாம் அல்லது விருந்தினர்களை உடனடியாக அகற்றலாம்.",
    "hostControlsHeader": "ஹோஸ்ட் கட்டுப்பாடுகள் & அறை மேலாண்மை",
    "hostPlayControlCheck": "வீடியோ பிளேபேக் மீது ஹோஸ்ட் முழுக் கட்டுப்பாட்டைக் கொண்டுள்ளது",
    "howItWorksLabel": "இது எப்படி வேலை செய்கிறது",
    "howWeCompare": "நாம் எப்படி ஒப்பிடுகிறோம்",
    "howWeCompareDesc": "பொதுவான திரைப் பகிர்வு தளங்களுடன் WatchTogether எவ்வாறு ஒப்பிடுகிறது என்பதைப் பார்க்கவும்.",
