    "privacyCardBody2": "நாங்கள் உங்கள் தரவை விற்கவோ, இலக்கு விளம்பரங்களைக் காட்டவோ அல்லது மூன்றாம் தரப்பினருடன் உங்கள் தகவலைப் பகிரவோ மாட்டோம். உங்கள் செயல்பாடு தனிப்பட்டதாக இருக்கும்.",
    "privacyCardBody3": "தனிப்பட்ட செய்திகளை நீக்கவும், முழு அரட்டை வரலாற்றையும் அழிக்கவும் அல்லது உங்கள் கணக்கை முழுவதுமாக அகற்றவும். உங்கள் தரவு, உங்கள் கட்டுப்பாடு.",
    "privacyCardTitle1": "எண்ட்-டு-எண்ட் என்க்ரிப்ட் செய்யப்பட்டது",
    "privacyCardTitle2": "தரவு விற்பனை இல்லை",
