    "faq": "FAQ",
    "faqA1": "ಇಲ್ಲ. ನಿಮ್ಮ ರೂಮ್ ಲಿಂಕ್ ಹೊಂದಿರುವ ಯಾರಾದರೂ ಅತಿಥಿಯಾಗಿ ತಕ್ಷಣ ಸೇರಿಕೊಳ್ಳಬಹುದು - ಯಾವುದೇ ಸೈನ್ ಅಪ್, ಇಮೇಲ್ ಇಲ್ಲ, ಡೌನ್‌ಲೋಡ್ ಅಗತ್ಯವಿಲ್ಲ. ಕೊಠಡಿಯನ್ನು ರಚಿಸಲು ಮಾತ್ರ ಖಾತೆಯ ಅಗತ್ಯವಿದೆ.",
    "faqA2": "ಇಲ್ಲ. YouTube, Twitch ಮತ್ತು Vimeo ಗಾಗಿ ಪ್ರತಿಯೊಬ್ಬರಿಗೂ ಲಿಂಕ್ ಅಗತ್ಯವಿದೆ. ಸ್ಥಳೀಯ ಫೈಲ್‌ಗಳಿಗೆ ಹೋಸ್ಟ್‌ಗೆ ಮಾತ್ರ ಫೈಲ್ ಅಗತ್ಯವಿದೆ - ಇದು ಎಲ್ಲರಿಗೂ ಸ್ಟ್ರೀಮ್ ಮಾಡುತ್ತದೆ. Netflix ಗೆ, ಹೋಸ್ಟ್‌ಗೆ ಮಾತ್ರ ಚಂದಾದಾರಿಕೆಯ ಅಗತ್ಯವಿದೆ.",
    "faqA3": "ಪ್ರಸ್ತುತ ವೀಡಿಯೊ ಎಲ್ಲಿ ಪ್ಲೇ ಆಗುತ್ತಿದೆ ಎಂಬುದನ್ನು ನಾವು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪತ್ತೆ ಮಾಡುತ್ತೇವೆ ಮತ್ತು ಆ ಕ್ಷಣಕ್ಕೆ ನೇರವಾಗಿ ನಿಮ್ಮನ್ನು ನೆಗೆಯುತ್ತೇವೆ. ನೀವು ಯಾವಾಗಲೂ ಕೊಠಡಿಯ ಉಳಿದ ಭಾಗದೊಂದಿಗೆ ತಕ್ಷಣವೇ ಸಿಂಕ್‌ನಲ್ಲಿರುವಿರಿ.",
    "faqA4": "ಒಂದೇ ಕೋಣೆಯಲ್ಲಿ ಒಂದೇ ಸಮಯದಲ್ಲಿ 50 ಜನರು ಒಟ್ಟಿಗೆ ವೀಕ್ಷಿಸಬಹುದು.",
    "faqA5": "ಹೌದು, ಬಳಸಲು ಸಂಪೂರ್ಣವಾಗಿ ಉಚಿತ. ಕೊಠಡಿಗಳನ್ನು ರಚಿಸಿ, ಸ್ನೇಹಿತರನ್ನು ಆಹ್ವಾನಿಸಿ ಮತ್ತು ಯಾವುದೇ ವೆಚ್ಚವಿಲ್ಲದೆ ಮತ್ತು ಕ್ರೆಡಿಟ್ ಕಾರ್ಡ್ ಅಗತ್ಯವಿಲ್ಲದೆ ಒಟ್ಟಿಗೆ ವೀಕ್ಷಿಸಿ.",
    "faqA6": "SahaPlay Chrome, Firefox, Safari ಮತ್ತು Edge ನಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. ಯಾವುದೇ ಪ್ಲಗಿನ್‌ಗಳು ಅಥವಾ ವಿಸ್ತರಣೆಗಳ ಅಗತ್ಯವಿಲ್ಲ. ಆಡಿಯೊದೊಂದಿಗೆ ಸ್ಕ್ರೀನ್‌ಶೇರ್‌ಗಾಗಿ ನಾವು ಉತ್ತಮ ಫಲಿತಾಂಶಗಳಿಗಾಗಿ Chrome ಅನ್ನು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ.",
    "faqA7": "ಹೌದು — ಸ್ಕ್ರೀನ್‌ಶೇರ್ ವೈಶಿಷ್ಟ್ಯವನ್ನು ಬಳಸುವುದು. ಹೋಸ್ಟ್ ತಮ್ಮ ನೆಟ್‌ಫ್ಲಿಕ್ಸ್ ಅಥವಾ ಪ್ರೈಮ್ ಟ್ಯಾಬ್ ಅನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತಾರೆ ಮತ್ತು ರೂಮ್‌ನಲ್ಲಿರುವ ಪ್ರತಿಯೊಬ್ಬರೂ ಅದನ್ನು ನೈಜ ಸಮಯದಲ್ಲಿ ನೋಡುತ್ತಾರೆ. ಆ ಸೇವೆಗಳಿಗೆ ನಿಮಗೆ ಚಂದಾದಾರಿಕೆಯ ಅಗತ್ಯವಿದೆ.",
    "faqA8": "ಹೌದು. ಖಾಸಗಿ ಸಂದೇಶಗಳನ್ನು ಕಳುಹಿಸುವ ಮೊದಲು ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಅಂತ್ಯದಿಂದ ಕೊನೆಯವರೆಗೆ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗುತ್ತದೆ. ಇದರರ್ಥ ನೀವು ಮತ್ತು ಸ್ವೀಕರಿಸುವವರು ಮಾತ್ರ ಅವುಗಳನ್ನು ಓದಬಹುದು - ನಾವಲ್ಲ, ಬೇರೆ ಯಾರೂ ಅಲ್ಲ.",
