    "privacyCardBody1": "ਸਾਰੇ ਨਿੱਜੀ ਸੁਨੇਹੇ ਭੇਜਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੀ ਡਿਵਾਈਸ 'ਤੇ ਐਨਕ੍ਰਿਪਟ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਅਸੀਂ ਸਿਰਫ ਏਨਕ੍ਰਿਪਟਡ ਸੰਸਕਰਣ ਨੂੰ ਸਟੋਰ ਕਰਦੇ ਹਾਂ - ਅਸੀਂ ਉਹਨਾਂ ਨੂੰ ਪੜ੍ਹ ਨਹੀਂ ਸਕਦੇ।",
    "privacyCardBody2": "ਅਸੀਂ ਤੁਹਾਡਾ ਡੇਟਾ ਨਹੀਂ ਵੇਚਦੇ, ਨਿਯਤ ਵਿਗਿਆਪਨ ਨਹੀਂ ਦਿਖਾਉਂਦੇ, ਜਾਂ ਤੀਜੀ ਧਿਰਾਂ ਨਾਲ ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸਾਂਝੀ ਨਹੀਂ ਕਰਦੇ। ਤੁਹਾਡੀ ਗਤੀਵਿਧੀ ਨਿੱਜੀ ਰਹਿੰਦੀ ਹੈ।",
    "privacyCardBody3": "ਵਿਅਕਤੀਗਤ ਸੁਨੇਹਿਆਂ ਨੂੰ ਮਿਟਾਓ, ਪੂਰੇ ਚੈਟ ਇਤਿਹਾਸ ਨੂੰ ਸਾਫ਼ ਕਰੋ, ਜਾਂ ਆਪਣੇ ਖਾਤੇ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਹਟਾਓ। ਤੁਹਾਡਾ ਡੇਟਾ, ਤੁਹਾਡਾ ਨਿਯੰਤਰਣ।",
